fn check(ok:bool){if !ok{let _=fail(0);}}fn fail(x:u8)->u8{1/x}
struct S(u8);struct T(u8);impl core::cmp::PartialEq<T> for S{fn eq(&self,r:&T)->bool{self.0==r.0}fn ne(&self,_:&T)->bool{false}}impl core::cmp::PartialOrd<T> for S{fn partial_cmp(&self,_:&T)->Option<core::cmp::Ordering>{Some(core::cmp::Ordering::Equal)}fn lt(&self,_:&T)->bool{true}fn le(&self,_:&T)->bool{false}fn gt(&self,_:&T)->bool{true}fn ge(&self,_:&T)->bool{false}}fn main(){let a=S(1);let b=T(2);check(!<&S as core::cmp::PartialEq<&T>>::eq(&&a,&&b));check(!<&S as core::cmp::PartialEq<&T>>::ne(&&a,&&b));check(<&S as core::cmp::PartialOrd<&T>>::lt(&&a,&&b));check(!<&S as core::cmp::PartialOrd<&T>>::le(&&a,&&b));check(<&S as core::cmp::PartialOrd<&T>>::gt(&&a,&&b));check(!<&S as core::cmp::PartialOrd<&T>>::ge(&&a,&&b));}